"use strict";(self["webpackChunkmy_vue_project"]=self["webpackChunkmy_vue_project"]||[]).push([[230],{9230:function(e,S,L){L.r(S),L.d(S,{digitalExperimentContent:function(){return t}});const t={"digital-exp-1":{title:"组合逻辑研究实验（一）",purpose:["一、实验目的","1. 了解并掌握用SSI器件实现简单组合逻辑电路的方法。","2. 了解编码、译码与显示的工作原理。","3. 掌握用MSI器件实现4位全加器的方法,并掌握全加器的应用。"],equipment:["二、实验所用仪器设备","1. 万用表          1台；","2. 直流稳压电源    1台；","3. 数字电路实验板  1套；","4. 计算机          1台。"],content_requirements:["三、实验任务及要求","1. 基本实验器件","给定器件为：四2输入异或门（74LS86）1只，四2输入与非门（74LS00）1只，六反相器（74LS04）1只，三3输入与非门（74LS10）1只，4位二进制全加器（74LS283）1只，8线-3线优先编码器（74LS148）1只，七段字形译码器（74LS48）1只,共阴极数码管（LTS-547RF）1只，4位并行比较器（741S85）1只。","2. 基本命题","（1） 参照实验教材图4-1-3（见本报告图1）连接实验电路，输入加逻辑开关，输出加LED显示器，测试三变量多数表决器的功能，并记录真值表。","（2） 用四2输入异或门74LS86和四2输入与非门74LS00组成1位全加器电路，参考实验教材图4-1-1（见本报告图2）。输入加逻辑开关，输出加LED显示器，测试其功能，并记录真值表。","（3） 用MSI器件74LS283实现4位全加器电路，用译码-显示电路显示其全加和,并将结果填入实验教材示例表4-1-1中（见本报告表1）。","3. 实验要求","熟悉实验命题后，先进行电路的设计，然后在计算机上进行虚拟仿真实验。","仿真运行正确后，再在实验板上搭建硬件电路，观察并记录实验结果，对实验过程和结果进行分析整理，最后撰写实验报告、整理文档，对实验进行总结。"]},"digital-exp-2":{title:"组合逻辑研究实验（二）",purpose:["一、实验目的","1. 了解译码器、数据选择器的工作原理及其功能。","2. 掌握用译码器，数据选择器实现组合逻辑电路的方法。"],equipment:["二、实验所用仪器设备","1. 万用表          1台；","2. 直流稳压电源    1台；","3. 数字电路实验板  1套；","4. 计算机          1台。"],content_requirements:["三、实验任务及要求","1. 基本实验器件","给定器件为3线-8线译码器（74LS138）1只，8选1数据选择器（74LS151）1只，双2线-4线译码器（74LS139）一只，双4选1数据选择器（74LS153）1只，三3输入与非门（74LS10）1只，双4输入与非门（74LS20）1只，四2输入与非门（74LS00）1只，七段字形译码器（74LS48）1只，共阴极数码管（LTS-547RF）1只。","2. 基本命题","（1） 用3-8译码器74LS138和门电路实现三变量多数表决器电路（参考教材图4-2-3）。用逻辑开关控制输入，用LED显示输出结果，记录输入输出对应真值表。","（2） 用8选1数据选择器（74LS151）实现函数：","。","用逻辑开关控制输入，用LED显示输出结果，记录输入输出对应真值表。","（3）用3-8译码器74LS138和门电路实际一个数字显示报警电路。","要求：用译码器、显示电路来显示，装置共有3个警报信号，当第一路有警报信号时，数码管显示1；当第二路有警报信号时，数码管显示2；当第三路有警报信号时，数码管显示3；当两路以上有警报信号时，数码管显示8；当无警报信号时，数码管显示0。","用逻辑开关控制输入，用数码管显示输出，记录输入对应输出。","4. 实验要求","熟悉实验命题后，先进行电路的设计，然后在计算机上进行虚拟仿真实验。","仿真运行正确后，再在实验板上搭建硬件电路，观察并记录实验结果，对实验过程和结果进行分析整理，最后撰写实验报告、整理文档，对实验进行总结。"]},"digital-exp-3":{title:"集成触发器实验",purpose:["一、实验目的","1. 熟悉常用触发器的基本结构及其逻辑功能。","2. 能用触发器设计基本的时序逻辑电路。"],equipment:["二、实验所用仪器设备","1. 万用表          1台；","3. 函数信号发生器  1套；","5. 数字电路实验版  1台；","2. 直流稳压电源    1台；","4. 双踪示波器      1台；","6. 计算机          1台。"],content_requirements:["三、实验任务及要求","1. 基本实验器件","给定器件为：双D触发器(74LS74)1只，双JK触发器(74LS76)1只，四2输入异或门(74LS86)1只，六反相器(74lS04)1只。","2. 基本命题","（1） 用D触发器74LS74构成一个异步的四进制减法计数器，并进行逻辑功能的验证。","a. 用单脉冲输入，触发器状态用指示灯显示。","b. 用1kHz连续脉冲输入，用示波器比较其输入、输出信号波形，记录波形图。","（2） 用JK触发器74LS76构成一个同步四进制加法计数器，并进行逻辑功能的验证。","a. 用单脉冲输入，触发器状态用指示灯显示。","b. 用1kHz连续脉冲输入，用示波器比较其输入、输出信号波形，记录波形图。","（3）用D触发器74LS74和与非门74LS00设计一个广告流水灯异步时序电路，广告流水灯有4个灯，这4个灯始终是一暗三明且暗灯循环右移，其示意图如下图所示，图中¤表示灯亮，◎表示灯暗。用示波器比较其输入、输出信号波形，记录波形图。","图1 广告流水灯示意图","4. 实验要求","根据试验任务，先进行电路的设计，然后在计算机上进行虚拟实验，仿真结果正确后，在实验板上搭建实验电路，利用指示部件或仪器观察实验结果是否正确，如果不正确，查找故障直至正确为止。最后一项工作是撰写实验报告、整理文档，对实验进行总结。"]},"digital-exp-4":{title:"计数器及其应用研究实验",purpose:["一、实验目的","1. 熟悉计数器的工作原理，掌握中规模计数器(MSI)逻辑功能及其应用。","2. 掌握计数器的级联方法，并会用中规模计数器实现任意进制计数器。"],equipment:["二、实验所用仪器设备","1. 万用表          1台；","3. 函数信号发生器  1套；","5. 逻辑分析仪      1台；","2. 直流稳压电源    1台；","4. 双踪示波器      1台；","6. 数字电路实验版  1台；","7. 计算机          1台。"],content_requirements:["三、实验任务及要求","1. 基本命题实验器件","给定器件为：二-五-十进制异步计数器(74LS90)1只，二进制同步计数器(74LS161)1只，双时钟BCD同步加/减计数器(74LS192)1只，七段字形译码器(74LS48)1只，共阴极数码管(LTS-547RF)1只，8选1数据选择器(74LS151)1只，四2输入与非门(74LS00)1只，三3输入与非门(74LS10)1只，六反相器(74L04)1只。","2. 基本命题","（1） 用4位二进制同步计数器74LS161和与非门设计M=7加法计数器(用两种方法实现)。","a. 用1Hz方波脉冲输入，计数器输送入译码、显示电路，记录计数状态的变化。","b. 用1kHz方波脉冲输入，用示波器示波器双踪观察并记录其输入、输出信号波形。","（2） 用两片74LS161和门电路设计模50计数器。要求完成电路设计并搭建电路。","a. 用1Hz方波脉冲输入，将计数器输出接译码、显示电路，在数码管上观察输出状态变化。","b. 用1kHz方波脉冲输入，用示波器示波器双踪观察其输入和50分频的信号波形。","，","3. 实验要求","拿到题目以后，先进行电路的设计、计算，然后在计算机上进行虚拟实验，运行正确以后，在实验板上搭建硬件电路，在指示灯或仪器上观察实验结果是否正确，如果不正确，查找故障直至正确为止。最后一项工作是撰写实验报告、整理文档，对实验进行总结。"]},"digital-exp-5":{title:"移位寄存器及其应用实验",purpose:["一、实验目的","1. 熟悉移位寄存器的结构及工作原理。","2. 掌握移位寄存器的应用。"],equipment:["二、实验所用仪器设备","1. 万用表          1台；","3. 函数信号发生器  1台；","5. 逻辑分析仪      1台；","7. 计算机          1台。","2. 直流稳压电源    1台；","4. 双踪示波器      1台；","6. 数字电路实验版  1台；"],content_requirements:["三、实验任务及要求","1. 基本实验器件","给定器件为：双向移位寄存器（74LS194）1只，3线-8线译码器（74LS138）1只，二进制同步计数器（74LS161）1只，三3输人或非门（74S27）1只，四2输入与门（741S08）1只，六反相器（74104）1只。","2. 基本命题","（1） 用双向移位寄存器（74LS194）与门电路构成具有自启动特性的环形计数器，用示波器双踪观察并记录输入、输出波形。","（2）用双向移位寄存器（74LS194）与门电路构成具有自启动特性的扭环形计数器，用示波器双踪观察并记录输入、输出波形。","（3） 用双向移位寄存器（741S194）和门电路构成M=7的移位型计数器(具有自启动特性)，用示波器双踪观察并记录输入、输出波形。。","3. 实验要求","根据试验任务，先进行电路的设计，然后在计算机上进行虚拟实验，仿真结果正确后，在实验板上搭建实验电路，利用指示部件或仪器观察实验结果是否正确，如果不正确，查找故障直至正确为止。最后一项工作是撰写实验报告、整理文档，对实验进行总结。"]},"digital-exp-6":{title:"序列码发生器的设计实验",purpose:["一、实验目的","1. 掌握用中规模器件设计序列码发生器的方法"],equipment:["二、实验所用仪器设备","1. 万用表          1台；","3. 函数信号发生器  1台；","5. 逻辑分析仪      1台；","7. 计算机          1台。","2. 直流稳压电源    1台；","4. 双踪示波器      1台；","6. 数字电路实验版  1台；"],content_requirements:["三、实验任务及要求","1. 基本实验器件","给定器件为：双向移位寄存器（74LS194）1只，二进制同步计数器（74LS161）1只，8选1数据选择器(74LS151)1只，四2输入与非门(74LS00)1只，三3输入与非门(74LS10)1只，六反相器(74L04)1只。","2. 基本命题","（1）用74LS161和74LS151设计一个计数型序列码产生器，产生的序列码为1101000101。","（2）同样的序列码，设计成移位型序列产生器，用74LS194来实现它，画出实验电路图，并验证之。","3. 实验要求","根据试验任务，先进行电路的设计，然后在计算机上进行虚拟实验，仿真结果正确后，在实验板上搭建实验电路，利用指示部件或仪器观察实验结果是否正确，如果不正确，查找故障直至正确为止。最后一项工作是撰写实验报告、整理文档，对实验进行总结。"]}}}}]);
